package com.savanna.backend.integration.contestkorea;

import java.sql.*;
import java.util.*;

/** Explicit pre-JPA migration: legacy enum strings must be converted before Hibernate reads them. H2 only. */
public final class ContestKoreaFieldMigration {
    private ContestKoreaFieldMigration() {}
    public static void apply(String url,String username,String password,List<Map<String,String>> csv) throws SQLException {
        if(!url.startsWith("jdbc:h2:file:")&&!url.startsWith("jdbc:h2:mem:"))throw new IllegalArgumentException("H2 migration only");
        try(var c=DriverManager.getConnection(url+(url.contains("IFEXISTS=")?"":";IFEXISTS=TRUE"),username,password)) {
            var metadata=c.getMetaData();try(var tables=metadata.getTables(null,null,"ANNOUNCEMENTS",null)){if(!tables.next())throw new SQLException("Existing announcements table is required");}
            var drops=new ArrayList<String>();
            try(var s=c.createStatement();var r=s.executeQuery("select t.CONSTRAINT_NAME,c.CHECK_CLAUSE from INFORMATION_SCHEMA.TABLE_CONSTRAINTS t join INFORMATION_SCHEMA.CHECK_CONSTRAINTS c on t.CONSTRAINT_SCHEMA=c.CONSTRAINT_SCHEMA and t.CONSTRAINT_NAME=c.CONSTRAINT_NAME where t.TABLE_NAME='ANNOUNCEMENTS' and t.CONSTRAINT_TYPE='CHECK'")){
                while(r.next())if(r.getString(2).toUpperCase(java.util.Locale.ROOT).contains("\"FIELD\""))drops.add(r.getString(1));
            }
            try(var s=c.createStatement()){
                for(var name:drops)s.execute("ALTER TABLE announcements DROP CONSTRAINT \""+name.replace("\"","\"\"")+"\"");
                s.execute("ALTER TABLE announcements ALTER COLUMN field VARCHAR(50)");
                for(String column:List.of("external_category_codes VARCHAR(512)","primary_category_codes VARCHAR(512)","classification_issue VARCHAR(255)","exclude_reason TEXT","date_source VARCHAR(255)"))s.execute("ALTER TABLE announcements ADD COLUMN IF NOT EXISTS "+column);
                s.execute("CREATE TABLE IF NOT EXISTS announcement_source_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,announcement_id BIGINT,external_id VARCHAR(100),source VARCHAR(50),event_type VARCHAR(80),details TEXT,recorded_at TIMESTAMP)");
            }
            var csvById=new HashMap<String,Map<String,String>>();csv.forEach(row->csvById.put(row.get("api_id"),row));
            var records=new ArrayList<Map<String,Object>>();
            try(var s=c.createStatement();var r=s.executeQuery("select announcement_id,external_id,field,external_category,source_url,source_provider,external_category_codes,primary_category_codes,classification_issue from announcements")){
                while(r.next()){var row=new HashMap<String,Object>(); for(var k:List.of("announcement_id","external_id","field","external_category","source_url","source_provider","external_category_codes","primary_category_codes","classification_issue"))row.put(k,r.getObject(k));records.add(row);}
            }
            int changed=0,unresolved=0;
            for(var row:records){String old=(String)row.get("field"),id=(String)row.get("external_id");var evidence=codes((String)row.get("primary_category_codes"));var observed=codes((String)row.get("external_category_codes"));
                ContestKoreaCategory.fromSource((String)row.get("external_category")).ifPresent(x->evidence.add(x.code()));
                String sourceUrl=(String)row.get("source_url");
                if(sourceUrl!=null){var matcher=java.util.regex.Pattern.compile("(?:[?&])Txt_bcode=(\\d+)(?:&|$)").matcher(sourceUrl);if(matcher.find())ContestKoreaCategory.fromSource(matcher.group(1)).ifPresent(x->observed.add(x.code()));}
                var supplementary=csvById.get(id);String issue="UNSUPPORTED_CSV_CATEGORY".equals(row.get("classification_issue"))?"UNSUPPORTED_CSV_CATEGORY":null;
                if(supplementary!=null){var category=ContestKoreaCategory.fromSource(supplementary.get("category_source"));if(category.isPresent()){evidence.add(category.get().code());issue=null;}else issue="UNSUPPORTED_CSV_CATEGORY";}
                observed.addAll(evidence);if(evidence.isEmpty())evidence.addAll(observed);
                if(evidence.isEmpty()&&old==null&&row.get("classification_issue")!=null)issue=(String)row.get("classification_issue");
                String mapped=null;
                if(issue==null&&evidence.size()==1)mapped=ContestKoreaCategory.fromSource(evidence.first()).orElseThrow().field().name();
                else if(issue==null&&evidence.size()>1)issue="CONFLICTING_SOURCE_CATEGORY";
                else if(issue==null&&old!=null)mapped=switch(old){case "DEVELOPMENT_HACKATHON"->"ACADEMIC_SCIENCE_IT";case "IDEA_PLANNING"->"IDEA_ARCHITECTURE_STARTUP";case "DESIGN"->"ART_DESIGN_WEBTOON";case "ACADEMIC_SCIENCE_IT","IDEA_ARCHITECTURE_STARTUP","ART_DESIGN_WEBTOON"->old;default->null;};
                if(mapped==null&&old!=null&&issue==null)issue="UNVERIFIED_LEGACY_CATEGORY";
                if(!Objects.equals(old,mapped)||issue!=null){changed++;if(issue!=null)unresolved++;
                    try(var p=c.prepareStatement("insert into announcement_source_events(announcement_id,external_id,source,event_type,details,recorded_at) values(?,?,'MIGRATION','FIELD_MAPPING',?,CURRENT_TIMESTAMP)")){
                        p.setObject(1,row.get("announcement_id"));p.setString(2,id);p.setString(3,tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(Map.of("previous",String.valueOf(old),"selected",String.valueOf(mapped),"evidence",evidence,"issue",String.valueOf(issue))));p.executeUpdate();}
                    System.out.println("CONTEST_KOREA_FIELD_MIGRATION id="+row.get("announcement_id")+" externalId="+id+" previous="+old+" selected="+mapped+" issue="+issue);
                }
                try(var p=c.prepareStatement("update announcements set field=?,classification_issue=?,external_category_codes=?,primary_category_codes=?,date_source=coalesce(date_source,case when source_provider='CONTEST_KOREA' then 'API_ESTIMATED' else 'MANUAL' end) where announcement_id=?")){
                    p.setString(1,mapped);p.setString(2,issue);p.setString(3,String.join("|",observed));p.setString(4,String.join("|",evidence));p.setObject(5,row.get("announcement_id"));p.executeUpdate();}
            }
            try(var s=c.createStatement()){
                s.execute("ALTER TABLE announcements ADD CONSTRAINT ck_announcement_field_v2 CHECK (field IS NULL OR field IN ('ACADEMIC_SCIENCE_IT','IDEA_ARCHITECTURE_STARTUP','ART_DESIGN_WEBTOON'))");
                for(String column:List.of("theme","evaluation_criteria","submission_requirements","enrollment_requirement"))s.execute("UPDATE announcements SET "+column+"=NULL WHERE TRIM("+column+") IN ('원문 참고','원문참고','원문 확인','공고 원문을 확인해 주세요')");
            }
            System.out.println("CONTEST_KOREA_FIELD_MIGRATION_RESULT changed="+changed+" unresolved="+unresolved);
        }
    }
    private static TreeSet<String> codes(String value){return value==null||value.isBlank()?new TreeSet<>():new TreeSet<>(List.of(value.split("\\|")));}
}
